 import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture as nodeTexture, uv as uvNode, positionLocal, normalLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Vector3, Color, DoubleSide, DataTexture } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const group = new Group();
  group.name = config.id ?? 'features-stat-tile';

  const width = 2.4;
  const height = 1.5;

  // Machined-metal backing plane
  const backingGeo = new PlaneGeometry(width + 0.2, height + 0.2);
  const backingMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.65,
    metalness: 0.35,
    clearcoat: 0.12,
    side: DoubleSide
  });
  const backing = new Mesh(backingGeo, backingMat);
  backing.position.z = -0.08;
  group.add(backing);

  // Accent edge plane (only the border remains visible behind the tile)
  const edgeGeo = new PlaneGeometry(width + 0.06, height + 0.06);
  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.0,
    depthWrite: false,
    side: DoubleSide
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.02;
  group.add(edge);

  // Displacement-mapped parallax plane
  const planeGeo = new PlaneGeometry(width, height, 64, 64);
  const planeMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.55,
    metalness: 0.45,
    clearcoat: 0.15,
    side: FrontSide
  });

  const displacementScale = 0.28;
  const blankDepth = new DataTexture(new Uint8Array([128, 128, 128]), 1, 1);
  blankDepth.needsUpdate = true;

  const buildPositionNode = (depthTex) => {
    const disp = nodeTexture(depthTex, uvNode()).r.sub(0.5).mul(displacementScale);
    return positionLocal.add(normalLocal.mul(disp));
  };

  planeMat.positionNode = buildPositionNode(blankDepth);
  planeMat.needsUpdate = true;

  const plane = new Mesh(planeGeo, planeMat);
  group.add(plane);

  // Rim/accent light for the machined surface
  const rim = new THREE.PointLight(new Color(colors.accent), 0.85, 6);
  rim.position.set(1.2, 0.8, 1.6);
  group.add(rim);

  const fill = new THREE.PointLight(new Color(colors.paper), 0.55, 6);
  fill.position.set(-1.0, -0.6, 1.4);
  group.add(fill);

  // Text content bridge (none for this tile, but wired generally)
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const textMesh = ctx.fontAtlas.createText(String(item.text ?? ''), {
      fontSize: item.typography?.fontSize ?? 0.13,
      color: item.role === 'accent' ? colors.accent : colors.paper,
      align: 'left'
    });
    textMesh.position.set(-width * 0.38, 0, 0.02);
    group.add(textMesh);
  }

  // Cinematic primitive: parallax-scroll
  const parallaxParams = config.cinematicPrimitives?.find(
    (p) => p.name === 'parallax-scroll'
  )?.params ?? { intensity: 0.25 };

  const parallax = ctx.primitives['parallax-scroll'](group, parallaxParams);

  // Async asset loading
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (!group.userData.isCleaned) {
        tex.colorSpace = THREE.SRGBColorSpace;
        planeMat.map = tex;
        planeMat.needsUpdate = true;
      }
    }).catch(() => {});
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      if (!group.userData.isCleaned) {
        planeMat.positionNode = buildPositionNode(tex);
        planeMat.needsUpdate = true;
      }
    }).catch(() => {});
  }

  // Interaction animations
  let hoverTween = null;
  let pressTween = null;
  let edgeTween = null;

  const onPointerEnter = () => {
    hoverTween?.kill();
    hoverTween = gsap.to(group.position, {
      z: 0.15,
      duration: 0.45,
      ease: 'power2.out',
      overwrite: 'auto'
    });
    edgeTween?.kill();
    edgeTween = gsap.to(edgeMat, {
      opacity: 0.6,
      duration: 0.3,
      ease: 'power2.out'
    });
  };

  const onPointerLeave = () => {
    hoverTween?.kill();
    hoverTween = gsap.to(group.position, {
      z: 0,
      duration: 0.45,
      ease: 'power2.out',
      overwrite: 'auto'
    });
    pressTween?.kill();
    pressTween = gsap.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.18,
      ease: 'power2.out'
    });
    edgeTween?.kill();
    edgeTween = gsap.to(edgeMat, {
      opacity: 0.0,
      duration: 0.3,
      ease: 'power2.out'
    });
  };

  const onPointerDown = () => {
    pressTween?.kill();
    pressTween = gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)'
    });
  };

  const onPointerUp = () => {
    pressTween?.kill();
    pressTween = gsap.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.2,
      ease: 'power2.out'
    });
  };

  const onClick = () => {
    ctx.emit('hub-features.select', { nodeId: config.id });
  };

  group.userData.handlers = {
    pointerenter: onPointerEnter,
    pointerleave: onPointerLeave,
    pointerdown: onPointerDown,
    pointerup: onPointerUp,
    click: onClick
  };

  // Load entrance
  const entrance = gsap.fromTo(
    group.scale,
    { x: 0.9, y: 0.9, z: 0.9 },
    { x: 1, y: 1, z: 1, duration: 0.75, ease: 'power3.out' }
  );

  group.userData.isCleaned = false;
  group.userData.cleanup = () => {
    if (group.userData.isCleaned) return;
    group.userData.isCleaned = true;

    entrance.kill();
    hoverTween?.kill();
    pressTween?.kill();
    edgeTween?.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(edgeMat);

    parallax?.cleanup?.();

    planeGeo.dispose();
    backingGeo.dispose();
    edgeGeo.dispose();
    planeMat.dispose();
    backingMat.dispose();
    edgeMat.dispose();

    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
    });
  };

  return group;
}
